<?php require __DIR__.'/../../app/bootstrap.php';require_admin($pdo);if(isset($_GET['sync'])){try{$items=(new VtuProvider($config['vtu']))->plans();$pdo->beginTransaction();$n=0;foreach($items as $x){$network=$x['service_id']??'';$id=$x['variation_id']??null;$name=$x['data_plan']??'';$price=$x['price']??null;if($network&&$id&&$name&&is_numeric($price)){$s=$pdo->prepare('INSERT INTO data_plans(network,provider_plan_id,name,cost_price,sell_price,active) VALUES(?,?,?,?,?,1) ON DUPLICATE KEY UPDATE name=VALUES(name),cost_price=VALUES(cost_price),active=1');$s->execute([$network,$id,$name,$price,$price]);$n++;}}$pdo->commit();flash('success',"Synced {$n} data plans. Review sell prices before going live.");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}header('Location:/admin/plans.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$sell=(float)$_POST['sell_price'];$active=(int)($_POST['active']??0);if($sell>0)$pdo->prepare('UPDATE data_plans SET sell_price=?,active=? WHERE id=?')->execute([$sell,$active,$id]);flash('success','Plan updated.');header('Location:/admin/plans.php');exit;}$rows=$pdo->query('SELECT * FROM data_plans ORDER BY network,cost_price LIMIT 500')->fetchAll();require __DIR__.'/../../app/layout.php';header_html('Manage Plans');?><div class="section-head"><div><p class="eyebrow">VTU catalogue</p><h2>Data Plans</h2></div><a class="btn" href="/admin/plans.php?sync=1">Sync from API</a></div><div class="card"><div class="table-wrap"><table><tr><th>Network</th><th>Plan</th><th>Cost</th><th>Sell</th><th>Active</th><th>Save</th></tr><?php foreach($rows as $r):?><tr><form method="post"><td><?=e(strtoupper($r['network']))?></td><td><?=e($r['name'])?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"></td><td><?=money($r['cost_price'])?></td><td><input class="mini" type="number" step="0.01" name="sell_price" value="<?=e($r['sell_price'])?>"></td><td><input type="checkbox" name="active" value="1" <?=$r['active']?'checked':''?>></td><td><button class="btn small">Save</button></td></form></tr><?php endforeach;?></table></div></div><?php footer_html();
